package got.wildlife; import got.GOTItems; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.ai.goal.*; import net.minecraft.world.entity.animal.Animal; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.*; import net.minecraft.world.item.crafting.Ingredient; import net.minecraft.world.level.Level; import org.jetbrains.annotations.Nullable; public final class GOTDikDikEntity extends Animal { public GOTDikDikEntity(EntityType<? extends Animal> t,Level l){super(t,l);xpReward=1;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,12).add(Attributes.MOVEMENT_SPEED,.22).add(Attributes.FOLLOW_RANGE,16);} @Override protected void registerGoals(){goalSelector.addGoal(0,new FloatGoal(this));goalSelector.addGoal(1,new PanicGoal(this,1.5));goalSelector.addGoal(2,new BreedGoal(this,1));goalSelector.addGoal(3,new TemptGoal(this,1.2,Ingredient.of(Items.WHEAT),false));goalSelector.addGoal(4,new FollowParentGoal(this,1.2));goalSelector.addGoal(5,new WaterAvoidingRandomStrollGoal(this,1));goalSelector.addGoal(6,new LookAtPlayerGoal(this,Player.class,8));goalSelector.addGoal(7,new RandomLookAroundGoal(this));} @Override public boolean isFood(ItemStack s){return s.is(Items.WHEAT);} @Nullable @Override public GOTDikDikEntity getBreedOffspring(ServerLevel l,AgeableMob m){return (GOTDikDikEntity)getType().create(l);} @Override protected void dropCustomDeathLoot(DamageSource s,int looting,boolean hit){super.dropCustomDeathLoot(s,looting,hit);spawnAtLocation(isOnFire()?GOTItems.DEER_COOKED.get():GOTItems.DEER_RAW.get());} }